import type { Suggestion } from "@/lib/types";

/** Static content for the design mock. Removed once the AI is wired up. */
export const seedDoc = `# Q3 launch update

We are pleased to share that, after a great deal of work across several teams over the past quarter, the new onboarding flow is now live for all customers as of this Monday.

## What changed

New accounts now land on a three-step checklist instead of the old settings page. In the first week, 64% of new teams finished setup, up from 41% before the change. Teams that finished setup were also far more likely to invite a second person.

We also simplified the billing step. Billing was, in many ways, one of the most confusing parts of the old flow, and it was something that a lot of people found confusing.

## What's next

- Roll the checklist out to existing workspaces
- Add an **import from CSV** option to step two
- Track _time to first invite_ as the main success metric

> If anything in the new flow looks off, post in \`#onboarding\` and we'll take a look.

Thanks to everyone who helped get this out the door. The full results are on the [team page](https://example.com/onboarding).
`;

type SeedEdit = { quote: string; replacement: string; reason: string; /** text right after an insert point */ before?: string };

const seedEdits: SeedEdit[] = [
  {
    quote: "We are pleased to share that, after a great deal of work across several teams over the past quarter, the",
    replacement: "The",
    reason: "Lead with the news. The effort behind it can come later, if at all.",
  },
  {
    quote: ", and it was something that a lot of people found confusing",
    replacement: "",
    reason: "Says the first half of the sentence again.",
  },
  {
    quote: "",
    before: "\n- Add an **import",
    replacement: " in October",
    reason: "Give the rollout a date so other teams can plan around it.",
  },
];

/** Place seed edits the way the server will: by exact, unique match. */
export function seedSuggestions(doc: string): Suggestion[] {
  return seedEdits.map((e, i) => {
    const needle = e.quote || e.before!;
    const at = doc.indexOf(needle);
    if (at < 0 || doc.indexOf(needle, at + 1) >= 0) throw new Error(`seed edit ${i} is not unique`);
    return { id: `s${i + 1}`, from: at, to: at + e.quote.length, quote: e.quote, replacement: e.replacement, reason: e.reason };
  });
}

"use client";

import { defaultKeymap, history, historyKeymap } from "@codemirror/commands";
import { markdown } from "@codemirror/lang-markdown";
import { EditorState } from "@codemirror/state";
import { EditorView, drawSelection, keymap } from "@codemirror/view";
import { useEffect, useRef } from "react";
import { suggestionKeymap } from "@/lib/editor/keymap";
import { markdownLines } from "@/lib/editor/markdownLines";
import { suggestionsExtension } from "@/lib/editor/suggestions";
import { editorStyling } from "@/lib/editor/theme";

type Props = {
  initialDoc: string;
  onReady: (view: EditorView) => void;
  onUpdate: (view: EditorView) => void;
  onAsk: () => boolean;
};

/** Mounts CodeMirror once. All later interaction goes through the view. */
export function Editor({ initialDoc, onReady, onUpdate, onAsk }: Props) {
  const host = useRef<HTMLDivElement>(null);
  // keep callbacks fresh without rebuilding the editor
  const cb = useRef({ onUpdate, onAsk });
  cb.current = { onUpdate, onAsk };

  useEffect(() => {
    const view = new EditorView({
      parent: host.current!,
      state: EditorState.create({
        doc: initialDoc,
        extensions: [
          history(),
          drawSelection(),
          EditorView.lineWrapping,
          markdown(),
          markdownLines,
          editorStyling,
          suggestionsExtension,
          suggestionKeymap(() => cb.current.onAsk()),
          keymap.of([...defaultKeymap, ...historyKeymap]),
          EditorView.contentAttributes.of({ "aria-label": "Document", spellcheck: "true" }),
          EditorView.updateListener.of((u) => cb.current.onUpdate(u.view)),
        ],
      }),
    });
    onReady(view);
    return () => view.destroy();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return <div ref={host} className="doc-editor" />;
}

"use client";

import { forwardRef } from "react";
import { kindOf, type Suggestion } from "@/lib/types";

const kindLabel = { insert: "Insert", delete: "Delete", replace: "Replace" } as const;

type Props = {
  suggestion: Suggestion;
  active: boolean;
  hover: boolean;
  inline?: boolean;
  style?: React.CSSProperties;
  onAccept: () => void;
  onReject: () => void;
  onRefine: () => void;
  onFocus: () => void;
  onHover: (on: boolean) => void;
};

export const SuggestionCard = forwardRef<HTMLDivElement, Props>(function SuggestionCard(
  { suggestion, active, hover, inline, style, onAccept, onReject, onRefine, onFocus, onHover },
  ref,
) {
  const kind = kindOf(suggestion);
  const cls = ["sg-card", active && "is-active", hover && "is-hover", inline && "is-inline"].filter(Boolean).join(" ");

  return (
    <div
      ref={ref}
      className={cls}
      style={style}
      data-sid={suggestion.id}
      onMouseDown={(e) => {
        if (!(e.target as HTMLElement).closest("button")) onFocus();
      }}
      onMouseEnter={() => onHover(true)}
      onMouseLeave={() => onHover(false)}
    >
      <div className="sg-card__kind">
        <span className="sg-card__dot" aria-hidden />
        {kindLabel[kind]}
      </div>
      <p className="sg-card__reason">{suggestion.reason}</p>
      <div className="sg-card__actions">
        <button type="button" className="btn btn--accept" onClick={onAccept}>
          Accept
          {active && <kbd>⌥↵</kbd>}
        </button>
        <button type="button" className="btn btn--text" onClick={onReject}>
          Reject
          {active && <kbd>esc</kbd>}
        </button>
        <button type="button" className="btn btn--text" onClick={onRefine}>
          Refine
        </button>
      </div>
    </div>
  );
});

