  background: var(--accent-hover);
}

.btn--small {
  height: 24px;
  padding: 0 8px;
  font-size: var(--ui-12);
}

.icon-btn {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border: 0;
  border-radius: var(--r-2);
  background: none;
  color: var(--ink-2);
  cursor: pointer;
  transition:
    background-color var(--t-fast),
    color var(--t-fast);
}
.icon-btn:hover {
  background: var(--sunk);
  color: var(--ink);
}

