  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: var(--s-4);
  height: var(--bar-h);
  padding: 0 var(--s-3) 0 var(--s-5);
  background: var(--paper);
  border-bottom: 1px solid transparent;
  transition: border-color var(--t-fast);
}
.topbar.is-scrolled {
  border-bottom-color: var(--line);
}

.topbar__doc {
  display: flex;
  align-items: baseline;
  gap: var(--s-2);
  min-width: 0;
  flex: 0 1 auto;
  white-space: nowrap;
}
.topbar__crumb,
.topbar__sep {
  color: var(--ink-3);
}
.topbar__title {
  color: var(--ink-2);
  overflow: hidden;
  text-overflow: ellipsis;
}

.topbar__status {
  flex: 1;
  min-width: 0;
  color: var(--ink-3);
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.topbar__actions {
  display: flex;
  align-items: center;
  gap: var(--s-2);
}

.review-controls {
  display: flex;
  align-items: center;
  gap: 2px;
  margin-right: var(--s-2);
}
.review-controls__count {
  margin-right: var(--s-1);
  color: var(--ink-2);
}

/* ---------- stage: doc column centred, margin to its right ---------- */

.stage {
  display: grid;
  grid-template-columns:
    minmax(0, 1fr)
    var(--measure)
    minmax(calc(var(--margin-w) + var(--s-7) + var(--s-5)), 1fr);
  padding: var(--s-8) 0 40vh var(--s-5);
}

.doc-col {
  grid-column: 2;
  position: relative;
  min-width: 0;
}

.margin-col {
  grid-column: 3;
  position: relative;
}

/* ---------- suggestion cards ---------- */

.sg-card {
  position: absolute;
  top: 0;
  left: var(--s-7);
  width: var(--margin-w);
  padding: var(--s-3);
  background: var(--raised);
  border: 1px solid var(--line);
  border-radius: var(--r-3);
  font-family: var(--font-ui);
  transition:
    transform var(--t-move),
    border-color var(--t-fast),
    box-shadow var(--t-fast);
  animation: fade-in var(--t-enter);
}
.sg-card.is-hover {
  border-color: var(--line-strong);
}
.sg-card.is-active {
  z-index: 1;
  border-color: var(--line-strong);
  box-shadow: var(--shadow-card-active);
}

.sg-card__kind {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: var(--s-1);
  color: var(--ink-3);
  font-size: var(--ui-12);
}
.sg-card__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
}

.sg-card__reason {
  margin: 0 0 var(--s-3);
  color: var(--ink-2);
  font-size: var(--ui-14);
  line-height: 1.45;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  overflow: hidden;
}
.sg-card.is-active .sg-card__reason {
  -webkit-line-clamp: unset;
}

.sg-card__actions {
  display: flex;
  align-items: center;
  gap: var(--s-1);
}
.sg-card__actions .btn {
  height: 28px;
}
.sg-card__actions .btn--accept kbd {
  opacity: 0.75;
}

/* inline (narrow screens): a block in the document, under its paragraph */
.cm-card-slot {
  padding: var(--s-2) 0 var(--s-4);
  white-space: normal;
  cursor: default;
}
.sg-card.is-inline {
  position: static;
  width: auto;
  transform: none;
  font-size: var(--ui-13);
  line-height: 1.4;
  letter-spacing: -0.005em;
}

/* ---------- ask popover ---------- */

.ask {
  position: absolute;
  z-index: 30;
  width: 440px;
  max-width: 100%;
  padding: 6px;
  background: var(--raised);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-4);
  box-shadow: var(--shadow-pop);
  font-family: var(--font-ui);
  animation: pop-in var(--t-enter);
}

.ask__row {
  display: flex;
  align-items: center;
  gap: var(--s-2);
  height: 36px;
  padding: 0 6px;
}

.ask__mark {
  display: grid;
  place-items: center;
  flex: none;
  width: 18px;
  height: 18px;
  border-radius: 5px;
  background: var(--accent);
  color: var(--on-accent);
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0;
}

.ask__input {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--ink);
  font: 400 var(--ui-14) / 1 var(--font-ui);
  letter-spacing: -0.005em;
}
.ask__input::placeholder {
  color: var(--ink-3);
}

.ask__thinking {
  flex: 1;
  font-size: var(--ui-14);
}

.ask__enter {
  color: var(--ink-3);
  opacity: 1;
  transition: color var(--t-fast);
}
.ask__enter.is-ready {
  color: var(--ink-2);
}

.ask__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 2px;
  padding: var(--s-2) 6px 4px;
  border-top: 1px solid var(--line);
}

.chip {
  height: 24px;
  padding: 0 9px;
  border: 0;
  border-radius: var(--r-2);
  background: var(--sunk);
  color: var(--ink-2);
  font-size: var(--ui-12);
  font-weight: 500;
  cursor: pointer;
  transition:
    background-color var(--t-fast),
    color var(--t-fast);
}
.chip:hover {
  background: var(--line);
  color: var(--ink);
}

.ask__error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 6px 2px;
  color: var(--del-ink);
  font-size: var(--ui-13);
}

/* ---------- meta + mobile review bar ---------- */

.doc-meta {
  position: fixed;
  left: var(--s-5);
  bottom: var(--s-4);
  color: var(--ink-3);
  font-size: var(--ui-12);
}

.review-bar {
  position: fixed;
  inset: auto 0 0 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 2px;
  height: calc(52px + env(safe-area-inset-bottom));
  padding: 0 var(--s-3) env(safe-area-inset-bottom);
  background: var(--raised);
  border-top: 1px solid var(--line);
}
.review-bar__count {
  min-width: 52px;
  color: var(--ink-2);
  text-align: center;
  font-variant-numeric: tabular-nums;
}
.review-bar__spacer {
  flex: 1;
}

/* ---------- shimmer (no spinners) ---------- */

.shimmer-text {
  background: linear-gradient(90deg, var(--ink-3) 0%, var(--ink-3) 35%, var(--ink) 50%, var(--ink-3) 65%, var(--ink-3) 100%);
  background-size: 300% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: shimmer var(--shimmer-dur) linear infinite;
}

@keyframes shimmer {
  from {
    background-position: 100% 0;
  }
  to {
    background-position: 0% 0;
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
}

@keyframes pop-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
}

/* ---------- narrow screens ---------- */

@media (max-width: 760px) {
  .topbar {
    padding: 0 var(--s-2) 0 var(--s-4);
    gap: var(--s-2);
  }
  .topbar__crumb,
  .topbar__sep,
  .topbar__status,
  .review-controls,
  .doc-meta {
    display: none;
  }
  .topbar__doc {
    flex: 1;
  }

  .stage {
    grid-template-columns: minmax(0, 1fr);
    padding: var(--s-6) var(--s-4) 40vh;
  }
  .doc-col {
    grid-column: 1;
  }
  .margin-col {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .shimmer-text {
    animation: none;
    background: none;
    color: var(--ink-2);
  }
  .sg-card,
  .ask {
    animation-name: fade-in;
  }
  .sg-card {
    transition: border-color var(--t-fast);
  }
}

