"use client";

import type { EditorView } from "@codemirror/view";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { useCallback, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { paragraphAt } from "@/lib/editor/paragraph";
import {
  acceptAll,
  acceptSuggestion,
  cardSlot,
  focusSuggestion,
  getSuggestions,
  rejectAll,
  rejectSuggestion,
  setActive,
  setAskTarget,
  setHover,
  setInlineCards,
  setSuggestions,
  setThinking,
  type SuggestionState,
} from "@/lib/editor/suggestions";
import { seedDoc, seedSuggestions } from "@/lib/mock/seed";
import type { Range } from "@/lib/types";
import { AskPopover, type AskPhase } from "./AskPopover";
import { Editor } from "./Editor";
import { MarginCards } from "./MarginCards";
import { SuggestionCard } from "./SuggestionCard";
import { ThemeToggle } from "./ThemeToggle";

/** Static states for design screenshots. Goes away when the AI is wired up. */
export type DemoState = "default" | "ask" | "thinking";

type Ask = { phase: AskPhase; scope: "paragraph" | "selection"; target: Range };
type AskPos = { left: number; top: number };

const MOCK_NOTE = "The news is buried in the first paragraph. The rest needs only small cuts.";
const POPOVER_W = 440;

function useMediaQuery(query: string) {
  const [match, setMatch] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia(query);
    setMatch(mq.matches);
    const on = () => setMatch(mq.matches);
    mq.addEventListener("change", on);
    return () => mq.removeEventListener("change", on);
  }, [query]);
  return match;
}

const countWords = (text: string) => text.match(/[\p{L}\p{N}][\p{L}\p{N}'’-]*/gu)?.length ?? 0;
const sameRecord = (a: Record<string, number>, b: Record<string, number>) =>
  Object.keys(a).length === Object.keys(b).length && Object.keys(a).every((k) => Math.abs(a[k] - b[k]) < 0.5);

export function Workspace({ demo = "default" }: { demo?: DemoState }) {
  const viewRef = useRef<EditorView | null>(null);
  const docColRef = useRef<HTMLDivElement>(null);
  const marginRef = useRef<HTMLDivElement>(null);

  const [sg, setSg] = useState<SuggestionState | null>(null);
  const [anchors, setAnchors] = useState<Record<string, number>>({});
  const [ask, setAsk] = useState<Ask | null>(null);
  const [askPos, setAskPos] = useState<AskPos | null>(null);
  const [reviewing, setReviewing] = useState(false);
  const [note, setNote] = useState<string | null>(MOCK_NOTE);
  const [words, setWords] = useState(() => countWords(seedDoc));
  const [title, setTitle] = useState("Untitled");
  const [scrolled, setScrolled] = useState(false);
  const narrow = useMediaQuery("(max-width: 760px)");

  /* ----- layout: card anchors + popover position, read during CM's measure phase ----- */

  const scheduleMeasure = useCallback((view: EditorView) => {
    view.requestMeasure({
      key: "workspace-layout",
      read(view) {
        const st = getSuggestions(view.state);
        const marginTop = marginRef.current?.getBoundingClientRect().top ?? 0;
        const next: Record<string, number> = {};
        for (const s of st.items) {
          const c = view.coordsAtPos(s.from, 1);
          next[s.id] = (c ? c.top : view.lineBlockAt(s.from).top + view.documentTop) - marginTop;
        }

        let pos: AskPos | null = null;
        const target = st.askTarget ?? st.thinking;
        const col = docColRef.current?.getBoundingClientRect();
        if (target && col) {
          const start = view.coordsAtPos(target.from, 1);
          const end = view.coordsAtPos(target.to, -1);
          if (start && end) {
            const maxLeft = Math.max(0, col.width - POPOVER_W);
            pos = { left: Math.min(Math.max(0, start.left - col.left), maxLeft), top: end.bottom - col.top + 8 };
          }
        }
        return { next, pos };
      },
      write({ next, pos }) {
        setAnchors((prev) => (sameRecord(prev, next) ? prev : next));
        setAskPos((prev) => (prev && pos && prev.left === pos.left && prev.top === pos.top ? prev : pos));
      },
    });
  }, []);

  const onUpdate = useCallback(
    (view: EditorView) => {
      setSg(getSuggestions(view.state));
      setWords(countWords(view.state.doc.toString()));
      setTitle(view.state.doc.line(1).text.replace(/^#+\s*/, "").trim() || "Untitled");
      scheduleMeasure(view);
    },
    [scheduleMeasure],
  );

  /* ----- ask popover ----- */

  const openAsk = useCallback(() => {
    const view = viewRef.current;
    if (!view) return false;
    const sel = view.state.selection.main;
    const scope = sel.empty ? "paragraph" : "selection";
    const target = sel.empty ? paragraphAt(view.state, sel.head) : { from: sel.from, to: sel.to };
    view.dispatch({ effects: setAskTarget.of(target) });
    setAsk({ phase: "input", scope, target });
    return true;
  }, []);

  const closeAsk = useCallback(() => {
    viewRef.current?.dispatch({ effects: [setAskTarget.of(null), setThinking.of(null)] });
    setAsk(null);
    viewRef.current?.focus();
  }, []);

  const submitAsk = useCallback(() => {
    const view = viewRef.current;
    if (!view || !ask) return;
    view.dispatch({ effects: [setAskTarget.of(null), setThinking.of(ask.target)] });
    setAsk({ ...ask, phase: "thinking" });
    // Mock only: no model yet, so "thinking" just ends.
    window.setTimeout(closeAsk, 2400);
  }, [ask, closeAsk]);

  // Click outside closes the popover while it's waiting for input.
  useEffect(() => {
    if (ask?.phase !== "input") return;
    const onDown = (e: MouseEvent) => {
      if (!(e.target as HTMLElement).closest(".ask")) closeAsk();
    };
    document.addEventListener("mousedown", onDown);
    return () => document.removeEventListener("mousedown", onDown);
  }, [ask?.phase, closeAsk]);

  /* ----- review doc (mock: shimmer the whole doc, then re-seed) ----- */

  function reviewDoc() {
    const view = viewRef.current;
    if (!view || reviewing) return;
    setReviewing(true);
    setNote(null);
    view.dispatch({ effects: [setSuggestions.of([]), setThinking.of({ from: 0, to: view.state.doc.length })] });
    window.setTimeout(() => {
      setReviewing(false);
      setNote(MOCK_NOTE);
      let items: ReturnType<typeof seedSuggestions> = [];
      try {
        items = seedSuggestions(view.state.doc.toString());
      } catch {
        // the user edited the seeded text; nothing to show in the mock
      }
      view.dispatch({ effects: [setThinking.of(null), setSuggestions.of(items)] });
    }, 2000);
  }

  /* ----- setup ----- */

  const onReady = useCallback(
    (view: EditorView) => {
      viewRef.current = view;
      const doc = view.state.doc.toString();
      const effects = [setSuggestions.of(seedSuggestions(doc)), setActive.of("s1")];
      view.dispatch({ effects });

      if (demo === "ask") {
        const target = paragraphAt(view.state, doc.indexOf("New accounts"));
        view.dispatch({ effects: setAskTarget.of(target) });
        setAsk({ phase: "input", scope: "paragraph", target });
      } else if (demo === "thinking") {
        const target = paragraphAt(view.state, doc.indexOf("Thanks to everyone"));
        view.dispatch({ effects: setThinking.of(target) });
        setAsk({ phase: "thinking", scope: "paragraph", target });
      }
      onUpdate(view);
      document.fonts?.ready.then(() => scheduleMeasure(view));
    },
    [demo, onUpdate, scheduleMeasure],
  );

  useEffect(() => {
    viewRef.current?.dispatch({ effects: setInlineCards.of(narrow) });
  }, [narrow]);

  useEffect(() => {
    const on = () => setScrolled(window.scrollY > 4);
    on();
    window.addEventListener("scroll", on, { passive: true });
    return () => window.removeEventListener("scroll", on);
  }, []);

  // CodeMirror must re-measure when the inline card (a block widget) changes size.
  const activeId = sg?.active ?? null;
  useEffect(() => {
    if (!narrow || !activeId) return;
    const slot = cardSlot(activeId);
    const ro = new ResizeObserver(() => viewRef.current?.requestMeasure());
    ro.observe(slot);
    return () => ro.disconnect();
  }, [narrow, activeId]);

  /* ----- render ----- */

  const items = sg?.items ?? [];
  const activeIndex = items.findIndex((s) => s.id === activeId);
  const step = (dir: 1 | -1) => {
    const view = viewRef.current;
    if (!view || !items.length) return;
    const i = activeIndex < 0 ? (dir === 1 ? 0 : items.length - 1) : (activeIndex + dir + items.length) % items.length;
    focusSuggestion(view, items[i].id);
  };
  const withView = (fn: (v: EditorView) => void) => () => viewRef.current && fn(viewRef.current);
  const cardActions = {
    onAccept: (id: string) => withView((v) => acceptSuggestion(v, id))(),
    onReject: (id: string) => withView((v) => rejectSuggestion(v, id))(),
    onRefine: (_id: string) => {}, // wired with the API
    onFocus: (id: string) => withView((v) => v.dispatch({ effects: setActive.of(id) }))(),
    onHover: (id: string | null) => withView((v) => v.dispatch({ effects: setHover.of(id) }))(),
  };
  const activeSuggestion = items.find((s) => s.id === activeId);
  const count = `${items.length} suggestion${items.length === 1 ? "" : "s"}`;

  return (
    <div className="workspace">
      <header className={scrolled ? "topbar is-scrolled" : "topbar"}>
        <div className="topbar__doc">
          <span className="topbar__crumb">Drafts</span>
          <span className="topbar__sep" aria-hidden>
            /
          </span>
          <span className="topbar__title">{title}</span>
        </div>

        <div className="topbar__status" aria-live="polite">
          {reviewing ? <span className="shimmer-text">Reading the document…</span> : note}
        </div>

        <div className="topbar__actions">
          {items.length > 0 && (
            <div className="review-controls">
              <span className="review-controls__count">{count}</span>
              <button type="button" className="icon-btn" aria-label="Previous suggestion" onClick={() => step(-1)}>
                <ChevronLeft size={15} strokeWidth={1.75} />
              </button>
              <button type="button" className="icon-btn" aria-label="Next suggestion" onClick={() => step(1)}>
                <ChevronRight size={15} strokeWidth={1.75} />
              </button>
              <span className="divider" aria-hidden />
              <button type="button" className="btn btn--text" onClick={withView(acceptAll)}>
                Accept all
              </button>
              <button type="button" className="btn btn--text" onClick={withView(rejectAll)}>
                Reject all
              </button>
            </div>
          )}
          <button type="button" className="btn btn--secondary" onClick={reviewDoc} disabled={reviewing}>
            {reviewing ? <span className="shimmer-text">Reviewing…</span> : "Review doc"}
          </button>
          <ThemeToggle />
        </div>
      </header>

      <main className="stage">
        <div className="doc-col" ref={docColRef}>
          <Editor initialDoc={seedDoc} onReady={onReady} onUpdate={onUpdate} onAsk={openAsk} />
          {ask && askPos && (
            <AskPopover
              phase={ask.phase}
              scope={ask.scope}
              style={{ left: askPos.left, top: askPos.top }}
              onSubmit={submitAsk}
              onCancel={closeAsk}
            />
          )}
        </div>
        <div className="margin-col" ref={marginRef}>
          {!narrow && (
            <MarginCards items={items} anchors={anchors} active={activeId} hover={sg?.hover ?? null} {...cardActions} />
          )}
        </div>
      </main>

      {narrow &&
        activeSuggestion &&
        createPortal(
          <SuggestionCard
            inline
            suggestion={activeSuggestion}
            active
            hover={false}
            onAccept={() => cardActions.onAccept(activeSuggestion.id)}
            onReject={() => cardActions.onReject(activeSuggestion.id)}
            onRefine={() => cardActions.onRefine(activeSuggestion.id)}
            onFocus={() => {}}
            onHover={() => {}}
          />,
          cardSlot(activeSuggestion.id),
        )}

      {narrow && items.length > 0 && (
        <nav className="review-bar" aria-label="Suggestions">
          <button type="button" className="icon-btn" aria-label="Previous suggestion" onClick={() => step(-1)}>
            <ChevronLeft size={16} strokeWidth={1.75} />
          </button>
          <span className="review-bar__count">
            {activeIndex >= 0 ? `${activeIndex + 1} of ${items.length}` : count}
          </span>
          <button type="button" className="icon-btn" aria-label="Next suggestion" onClick={() => step(1)}>
            <ChevronRight size={16} strokeWidth={1.75} />
          </button>
          <span className="review-bar__spacer" />
          <button type="button" className="btn btn--text" onClick={withView(rejectAll)}>
            Reject all
          </button>
          <button type="button" className="btn btn--secondary" onClick={withView(acceptAll)}>
            Accept all
          </button>
        </nav>
      )}

      <footer className="doc-meta">
        {words} words <span aria-hidden>·</span> Saved
      </footer>
    </div>
  );
}

@import "./tokens.css";
@import "./editor.css";

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: var(--ui-13);
  line-height: 1.4;
  letter-spacing: -0.005em;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

button {
  font: inherit;
  letter-spacing: inherit;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

kbd {
  font: 500 11px/1 var(--font-ui);
  letter-spacing: 0;
  opacity: 0.7;
}

/* ---------- buttons ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 10px;
  border: 0;
  border-radius: var(--r-2);
  background: none;
  color: var(--ink-2);
  font-weight: 500;
  font-size: var(--ui-13);
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color var(--t-fast),
    color var(--t-fast),
    border-color var(--t-fast);
}
.btn:active:not(:disabled) {
  transform: translateY(0.5px);
}
.btn:disabled {
  cursor: default;
}

.btn--text:hover:not(:disabled) {
  background: var(--sunk);
  color: var(--ink);
}

.btn--secondary {
  background: var(--raised);
  border: 1px solid var(--line-strong);
  color: var(--ink);
}
.btn--secondary:hover:not(:disabled) {
  background: var(--sunk);
}

.btn--accept {
  background: var(--accent);
  color: var(--on-accent);
}
.btn--accept:hover {
  background: var(--accent-hover);
}

.btn--small {
  height: 24px;
  padding: 0 8px;
  font-size: var(--ui-12);
}

.icon-btn {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border: 0;
  border-radius: var(--r-2);
  background: none;
  color: var(--ink-2);
  cursor: pointer;
  transition:
    background-color var(--t-fast),
    color var(--t-fast);
}
.icon-btn:hover {
  background: var(--sunk);
  color: var(--ink);
}

.divider {
  width: 1px;
  height: 16px;
  margin: 0 var(--s-1);
  background: var(--line-strong);
}

/* ---------- top bar ---------- */

.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: var(--s-4);
  height: var(--bar-h);
  padding: 0 var(--s-3) 0 var(--s-5);
  background: var(--paper);
  border-bottom: 1px solid transparent;
  transition: border-color var(--t-fast);
}
.topbar.is-scrolled {
  border-bottom-color: var(--line);
}

.topbar__doc {
  display: flex;
  align-items: baseline;
  gap: var(--s-2);
  min-width: 0;
  flex: 0 1 auto;
  white-space: nowrap;
}
.topbar__crumb,
.topbar__sep {
  color: var(--ink-3);
}
.topbar__title {
  color: var(--ink-2);
  overflow: hidden;
  text-overflow: ellipsis;
}

.topbar__status {
  flex: 1;
  min-width: 0;
  color: var(--ink-3);
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.topbar__actions {
  display: flex;
  align-items: center;
  gap: var(--s-2);
}

.review-controls {
  display: flex;
  align-items: center;
  gap: 2px;
  margin-right: var(--s-2);
}
.review-controls__count {
  margin-right: var(--s-1);
  color: var(--ink-2);
}

/* ---------- stage: doc column centred, margin to its right ---------- */

.stage {
  display: grid;
  grid-template-columns:
    minmax(0, 1fr)
    var(--measure)
    minmax(calc(var(--margin-w) + var(--s-7) + var(--s-5)), 1fr);
  padding: var(--s-8) 0 40vh var(--s-5);
}

.doc-col {
  grid-column: 2;
  position: relative;
  min-width: 0;
}

.margin-col {
  grid-column: 3;
  position: relative;
}

/* ---------- suggestion cards ---------- */

.sg-card {
  position: absolute;
  top: 0;
  left: var(--s-7);
  width: var(--margin-w);
  padding: var(--s-3);
  background: var(--raised);
  border: 1px solid var(--line);
  border-radius: var(--r-3);
  font-family: var(--font-ui);
  transition:
    transform var(--t-move),
    border-color var(--t-fast),
    box-shadow var(--t-fast);
  animation: fade-in var(--t-enter);
}
.sg-card.is-hover {
  border-color: var(--line-strong);
}
.sg-card.is-active {
  z-index: 1;
  border-color: var(--line-strong);
  box-shadow: var(--shadow-card-active);
}

.sg-card__kind {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: var(--s-1);
  color: var(--ink-3);
  font-size: var(--ui-12);
}
.sg-card__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
}

.sg-card__reason {
  margin: 0 0 var(--s-3);
  color: var(--ink-2);
  font-size: var(--ui-14);
  line-height: 1.45;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  overflow: hidden;
}
.sg-card.is-active .sg-card__reason {
  -webkit-line-clamp: unset;
}

.sg-card__actions {
  display: flex;
  align-items: center;
  gap: var(--s-1);
}
.sg-card__actions .btn {
  height: 28px;
}
.sg-card__actions .btn--accept kbd {
  opacity: 0.75;
}

/* inline (narrow screens): a block in the document, under its paragraph */
.cm-card-slot {
  padding: var(--s-2) 0 var(--s-4);
  white-space: normal;
  cursor: default;
}
.sg-card.is-inline {
  position: static;
  width: auto;
  transform: none;
  font-size: var(--ui-13);
  line-height: 1.4;
  letter-spacing: -0.005em;
}

/* ---------- ask popover ---------- */

.ask {
  position: absolute;
  z-index: 30;
  width: 440px;
  max-width: 100%;
  padding: 6px;
  background: var(--raised);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-4);
  box-shadow: var(--shadow-pop);
  font-family: var(--font-ui);
  animation: pop-in var(--t-enter);
}

.ask__row {
  display: flex;
  align-items: center;
  gap: var(--s-2);
  height: 36px;
  padding: 0 6px;
}

.ask__mark {
  display: grid;
  place-items: center;
  flex: none;
  width: 18px;
  height: 18px;
  border-radius: 5px;
  background: var(--accent);
  color: var(--on-accent);
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0;
}

.ask__input {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--ink);
  font: 400 var(--ui-14) / 1 var(--font-ui);
  letter-spacing: -0.005em;
}
.ask__input::placeholder {
  color: var(--ink-3);
}

.ask__thinking {
  flex: 1;
  font-size: var(--ui-14);
}

.ask__enter {
  color: var(--ink-3);
  opacity: 1;
  transition: color var(--t-fast);
}
.ask__enter.is-ready {
  color: var(--ink-2);
}

.ask__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 2px;
  padding: var(--s-2) 6px 4px;
  border-top: 1px solid var(--line);
}

.chip {
  height: 24px;
  padding: 0 9px;
  border: 0;
  border-radius: var(--r-2);
  background: var(--sunk);
  color: var(--ink-2);
  font-size: var(--ui-12);
  font-weight: 500;
  cursor: pointer;
  transition:
    background-color var(--t-fast),
    color var(--t-fast);
}
.chip:hover {
  background: var(--line);
  color: var(--ink);
}

.ask__error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 6px 2px;
  color: var(--del-ink);
  font-size: var(--ui-13);
}

/* ---------- meta + mobile review bar ---------- */

.doc-meta {
  position: fixed;
  left: var(--s-5);
  bottom: var(--s-4);
  color: var(--ink-3);
  font-size: var(--ui-12);
}

.review-bar {
  position: fixed;
  inset: auto 0 0 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 2px;
  height: calc(52px + env(safe-area-inset-bottom));
  padding: 0 var(--s-3) env(safe-area-inset-bottom);
  background: var(--raised);
  border-top: 1px solid var(--line);
}
.review-bar__count {
  min-width: 52px;
  color: var(--ink-2);
  text-align: center;
  font-variant-numeric: tabular-nums;
}
.review-bar__spacer {
  flex: 1;
}

/* ---------- shimmer (no spinners) ---------- */

.shimmer-text {
  background: linear-gradient(90deg, var(--ink-3) 0%, var(--ink-3) 35%, var(--ink) 50%, var(--ink-3) 65%, var(--ink-3) 100%);
  background-size: 300% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: shimmer var(--shimmer-dur) linear infinite;
}

@keyframes shimmer {
  from {
    background-position: 100% 0;
  }
  to {
    background-position: 0% 0;
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
}

@keyframes pop-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
}

/* ---------- narrow screens ---------- */

@media (max-width: 760px) {
  .topbar {
    padding: 0 var(--s-2) 0 var(--s-4);
    gap: var(--s-2);
  }
  .topbar__crumb,
  .topbar__sep,
  .topbar__status,
  .review-controls,
  .doc-meta {
    display: none;
  }
  .topbar__doc {
    flex: 1;
  }

  .stage {
    grid-template-columns: minmax(0, 1fr);
    padding: var(--s-6) var(--s-4) 40vh;
  }
  .doc-col {
    grid-column: 1;
  }
  .margin-col {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .shimmer-text {
    animation: none;
    background: none;
    color: var(--ink-2);
  }
  .sg-card,
  .ask {
    animation-name: fade-in;
  }
  .sg-card {
    transition: border-color var(--t-fast);
  }
}

/* Document surface: line-level Markdown blocks and suggestion marks.
   CodeMirror's base theme lives in lib/editor/theme.ts. */

.doc-editor .cm-line.cm-h1 {
  font-size: var(--h1-size);
  line-height: 1.2;
  padding-bottom: 0.1em;
}
.doc-editor .cm-line.cm-h2 {
  font-size: var(--h2-size);
  line-height: 1.3;
  padding-top: 0.35em;
}
.doc-editor .cm-line.cm-h3 {
  font-size: var(--h3-size);
  line-height: 1.4;
  padding-top: 0.25em;
}
.doc-editor .cm-line.cm-h4 {
  font-size: 1em;
  line-height: var(--doc-leading);
}

/* blank lines between blocks: a paragraph gap, not a full empty line */
.doc-editor .cm-line.cm-gap {
  line-height: 0.95;
}

.doc-editor .cm-line.cm-quote {
  padding-left: 1em;
  border-left: 2px solid var(--line-strong);
  color: var(--ink-2);
}

.doc-editor .cm-line.cm-li {
  padding-left: 1.1em;
  text-indent: -1.1em;
}

.doc-editor .cm-line.cm-codeblock {
  padding: 0 0.9em;
  background: var(--sunk);
  font-family: var(--font-mono);
  font-size: 0.84em;
}

/* inline code gets a quiet chip */
.doc-editor .cm-content span[class*="ͼ"]:has(> *) {
  /* no-op: highlight classes are generated; inline code styled via theme.ts */
}

/* ---------- suggestions ---------- */

.cm-sg-del,
.cm-sg-ins {
  border-radius: var(--r-1);
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
  transition:
    background-color var(--t-fast),
    box-shadow var(--t-fast);
}

.cm-sg-del {
  color: var(--del-ink);
  background: var(--del-bg);
  text-decoration: line-through;
  text-decoration-color: var(--del-line);
  text-decoration-thickness: 1.5px;
}
/* dimmed markdown marks inside a deletion still read as deleted */
.cm-sg-del * {
  color: inherit;
}

.cm-sg-ins {
  color: var(--ins-ink);
  background: var(--ins-bg);
  text-decoration: underline;
  text-decoration-color: var(--accent);
  text-decoration-thickness: 1.5px;
  text-underline-offset: 3px;
  cursor: pointer;
}

.cm-sg-del.is-hover,
.cm-sg-del.is-active {
  background: var(--del-bg-strong);
}
.cm-sg-ins.is-hover,
.cm-sg-ins.is-active {
  background: var(--ins-bg-strong);
}
.cm-sg-del.is-active {
  box-shadow: 0 0 0 1px var(--del-line);
}
.cm-sg-ins.is-active {
  box-shadow: 0 0 0 1px var(--accent);
}

/* ---------- ask target + thinking ---------- */

.cm-ask-target {
  background: var(--selection);
  border-radius: var(--r-1);
}

.cm-thinking {
  background-image: linear-gradient(
    90deg,
    transparent 0%,
    transparent 30%,
    var(--ins-bg-strong) 50%,
    transparent 70%,
    transparent 100%
  );
  background-size: 300% 100%;
  animation: shimmer var(--shimmer-dur) linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  .cm-thinking {
    animation: none;
    background-image: none;
    background-color: var(--ins-bg);
  }
}

