mkdir -p scripts && cat > app/layout.tsx <<'EOF'
import type { Metadata, Viewport } from "next";
import { IBM_Plex_Mono, Inter, Source_Serif_4 } from "next/font/google";
import { themeInitScript } from "@/components/ThemeToggle";
import "./globals.css";

const serif = Source_Serif_4({
  subsets: ["latin"],
  style: ["normal", "italic"],
  axes: ["opsz"],
  variable: "--font-source-serif",
  display: "swap",
});
const sans = Inter({ subsets: ["latin"], variable: "--font-inter", display: "swap" });
const mono = IBM_Plex_Mono({ subsets: ["latin"], weight: ["400", "500"], variable: "--font-plex-mono", display: "swap" });

export const metadata: Metadata = {
  title: "Draft",
  description: "A Markdown editor with an AI co-author that suggests, never overwrites.",
};

export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
  themeColor: [
    { media: "(prefers-color-scheme: light)", color: "#fbf9f4" },
    { media: "(prefers-color-scheme: dark)", color: "#171614" },
  ],
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" className={`${serif.variable} ${sans.variable} ${mono.variable}`} suppressHydrationWarning>
      <head>
        <script dangerouslySetInnerHTML={{ __html: themeInitScript }} />
      </head>
      <body>{children}</body>
    </html>
  );
}
EOF
cat > app/page.tsx <<'EOF'
import { Workspace, type DemoState } from "@/components/Workspace";

/**
 * Design mock: seeded doc and fake suggestions, no AI yet.
 * `?state=ask` and `?state=thinking` show those states for screenshots.
 */
export default async function Page({ searchParams }: { searchParams: Promise<{ state?: string }> }) {
  const { state } = await searchParams;
  const demo: DemoState = state === "ask" || state === "thinking" ? state : "default";
  return <Workspace key={demo} demo={demo} />;
}
EOF
cat > scripts/screenshots.mjs <<'EOF'
// Design review screenshots: every state at 1440 and 390 wide, light and dark.
// Usage: npm run screenshots [-- http://localhost:3000]
import { mkdirSync } from "node:fs";
import { chromium } from "playwright";

const base = process.argv[2] ?? "http://localhost:3000";
const out = "design/screenshots";
mkdirSync(out, { recursive: true });

const widths = [
  { name: "1440", width: 1440, height: 960, scale: 1 },
  { name: "390", width: 390, height: 844, scale: 2 },
];
const themes = ["light", "dark"];
const states = ["default", "ask", "thinking"];

const browser = await chromium.launch();
for (const w of widths) {
  for (const theme of themes) {
    const ctx = await browser.newContext({
      viewport: { width: w.width, height: w.height },
      deviceScaleFactor: w.scale,
      colorScheme: theme,
      reducedMotion: "no-preference",
    });
    const page = await ctx.newPage();
    for (const state of states) {
      await page.goto(`${base}/?state=${state}`, { waitUntil: "networkidle" });
      await page.evaluate(() => document.fonts.ready);
      await page.waitForTimeout(350); // let cards settle after measuring
      const file = `${out}/${state}-${w.name}-${theme}.png`;
      await page.screenshot({ path: file, fullPage: state === "default" });
      console.log(file);
    }
    await ctx.close();
  }
}
await browser.close();
EOF
