cat > scripts/.smoke.mjs <<'EOF'
import { chromium } from "playwright";
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1440, height: 960 } });
const errs = []; p.on("pageerror", (e) => errs.push(e.message));
await p.goto("http://localhost:3123/", { waitUntil: "networkidle" });
await p.waitForSelector(".sg-card");
const doc = () => p.evaluate(() => document.querySelector(".cm-content").innerText);
const cards = () => p.locator(".sg-card").count();
const ok = (name, cond) => console.log(cond ? "PASS" : "FAIL", name);

// accept by card button (s2 = delete)
await p.locator('.sg-card[data-sid="s2"] .btn--accept').click();
ok("accept removes deleted text", !(await doc()).includes("a lot of people found confusing") && (await cards()) === 2);

// click insert text -> active, alt+enter accepts
await p.locator(".cm-sg-ins-wrap[data-sid='s3']").click();
await p.keyboard.press("Alt+Enter");
ok("alt+enter accepts insert", (await doc()).includes("workspaces in October") && (await cards()) === 1);

// esc rejects with cursor in suggestion
await p.locator(".cm-sg-ins-wrap[data-sid='s1']").click();
await p.keyboard.press("Escape");
ok("esc rejects", (await doc()).includes("We are pleased") && (await cards()) === 0);

// ⌘K opens popover on paragraph, esc closes
await p.locator(".cm-line", { hasText: "New accounts" }).click();
await p.keyboard.press("Meta+k");
ok("cmd+k opens ask", await p.locator(".ask").isVisible());
ok("ask target highlighted", (await p.locator(".cm-ask-target").count()) > 0);
await p.keyboard.press("Escape");
ok("esc closes ask", (await p.locator(".ask").count()) === 0);

// tab still indents a list item
await p.locator(".cm-line", { hasText: "Track" }).click();
await p.keyboard.press("Home");
await p.keyboard.press("Tab");
ok("tab indents list item", /\n\s+- Track/.test(await doc()));

// undo restores
for (let i = 0; i < 4; i++) await p.keyboard.press("Meta+z");
ok("undo restores accepted delete", (await doc()).includes("a lot of people found confusing"));
console.log("page errors:", errs);
await b.close();
EOF
node scripts/.smoke.mjs; rm scripts/.smoke.mjs

