    if (hits.length === 0) {
      const why = scope && occurrences(doc, e.quote, 1).length > 0 ? "outside_scope" : "not_found";
      dropped.push({ quote: e.quote, why });
      continue;
    }
    if (hits.length > 1) {
      dropped.push({ quote: e.quote, why: "ambiguous" });
      continue;
    }

