      r.skipped ? "skipped" : r.error ? `error` : `${passed}/${r.checks.length}`,
      r.res ? String(r.res.suggestions.length) : "-",
      r.res ? String(r.res.dropped.length) : "-",
      r.skipped ? "-" : `${(r.latencyMs / 1000).toFixed(1)} s`,
      r.skipped ? "-" : `$${r.costUsd.toFixed(4)}`,
    ];
  });

