// Design review screenshots at 1440 and 390, light and dark, driving the real UI
// with /api/suggest mocked in the browser (no model calls).
// Usage: npm run screenshots -- http://localhost:3000
import { mkdirSync } from "node:fs";
import { chromium } from "playwright";

const base = process.argv[2] ?? "http://localhost:3000";
const out = "design/screenshots";
mkdirSync(out, { recursive: true });

const widths = [
  { name: "1440", width: 1440, height: 960, scale: 1 },
  { name: "390", width: 390, height: 844, scale: 2 },
];

/** Three suggestions on the sample doc, placed the way the server places them. */
function fakeReview(doc) {
  const at = (quote, replacement, reason, anchor) => {
    const from = anchor ? doc.indexOf(anchor) + anchor.length : doc.indexOf(quote);
    return { id: quote || anchor, from, to: from + quote.length, quote, replacement, reason };
  };
  return {
    note: "Opened with the news and cut a repeated clause.",
    suggestions: [
      at("We are pleased to share that, after a great deal of work across several teams over the past quarter, the", "The", "Lead with the news. The effort behind it can come later, if at all."),
      at(", and it was something that a lot of people found confusing", "", "Says the first half of the sentence again."),
      at("", " in October", "Give the rollout a date so other teams can plan around it.", "existing workspaces"),
    ],
    dropped: [],
    usage: { inputTokens: 0, outputTokens: 0, costUsd: 0, latencyMs: 1 },
  };
}

const settle = (page) =>
  page.waitForFunction(() =>
    document.getAnimations().every((a) => a.effect.getTiming().iterations === Infinity || a.playState === "finished"),
  );

const browser = await chromium.launch();
for (const w of widths) {
  for (const theme of ["light", "dark"]) {
    const ctx = await browser.newContext({ viewport: { width: w.width, height: w.height }, deviceScaleFactor: w.scale, colorScheme: theme });
    const page = await ctx.newPage();
    let hang = false;
    await page.route("**/api/suggest", async (route) => {
      if (hang) return; // leave the ⌘K request pending to show the thinking state
      await route.fulfill({ json: fakeReview(route.request().postDataJSON().doc) });
    });

    // default: after Review doc
    await page.goto(base, { waitUntil: "networkidle" });
    await page.evaluate(() => document.fonts.ready);
    await page.getByRole("button", { name: "Review doc" }).click();
    await page.locator(".cm-sg-del").first().waitFor();
    await page.evaluate(() => {
      const v = window.__view;
      const at = v.state.doc.toString().indexOf("pleased");
      v.dispatch({ selection: { anchor: at }, userEvent: "select" }); // first suggestion active
    });
    await page.evaluate(() => document.activeElement.blur());
    await settle(page);
    await page.waitForTimeout(250);
    await page.screenshot({ path: `${out}/default-${w.name}-${theme}.png` });

    // ask: ⌘K on the "New accounts" paragraph
    await page.evaluate(() => {
      const v = window.__view;
      v.focus();
      v.dispatch({ selection: { anchor: v.state.doc.toString().indexOf("three-step") }, userEvent: "select" });
    });
    await page.keyboard.press("ControlOrMeta+k");
    await page.getByRole("dialog", { name: "Ask AI" }).waitFor();
    await settle(page);
    await page.waitForTimeout(250);
    await page.screenshot({ path: `${out}/ask-${w.name}-${theme}.png` });

    // thinking: submit and leave the request hanging
    hang = true;
    await page.getByRole("button", { name: "Tighten" }).click();
    await page.getByText("Thinking…").waitFor();
    await page.waitForTimeout(600);
    await page.screenshot({ path: `${out}/thinking-${w.name}-${theme}.png` });

    console.log(`${w.name} ${theme}: default, ask, thinking`);
    await ctx.close();
  }
}
await browser.close();

/**
 * Print the OpenRouter key's remaining credit (GET /api/v1/key; not a model
 * call, not billed). Only money fields are printed: the key's `label` can
 * contain a masked copy of the key.
 *
 *   npm run credit
 */
try {
  process.loadEnvFile(".env");
} catch {
  // rely on the environment
}
const key = process.env.OPENROUTER_API_KEY;
if (!key) {
  console.error("credit: OPENROUTER_API_KEY is not set");
  process.exit(1);
}
const res = await fetch("https://openrouter.ai/api/v1/key", { headers: { Authorization: `Bearer ${key}` } });
if (!res.ok) {
  console.error(`credit: HTTP ${res.status}`);
  process.exit(1);
}
const json = (await res.json()) as Record<string, unknown> & { data?: Record<string, unknown> };
const d = json.data ?? json;
const usd = (v: unknown) => (typeof v === "number" ? `$${v.toFixed(4)}` : "n/a");
console.log(`remaining ${usd(d.limit_remaining)} of ${usd(d.limit)} · used ${usd(d.usage)}`);

// One real run through the app, against the real API (costs money, ~1¢):
// Review doc → accept one → reject one → refine one twice → type while ⌘K runs.
// Screenshots each step into design/screenshots/live/. Stops after 6 model calls.
// Usage: node scripts/live-walkthrough.mjs http://localhost:3000
import { mkdirSync, writeFileSync } from "node:fs";
import { chromium } from "playwright";

const base = process.argv[2] ?? "http://localhost:3000";
const out = "design/screenshots/live";
const MAX_CALLS = 6;
mkdirSync(out, { recursive: true });

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 960 }, colorScheme: "light" });
const log = [];
let calls = 0;

await page.route("**/api/suggest", async (route) => {
  if (++calls > MAX_CALLS) return route.abort(); // budget guard
  const body = route.request().postDataJSON();
  const started = Date.now();
  const res = await route.fetch();
  const json = await res.json();
  log.push({ call: calls, mode: body.mode, scope: !!body.scope, instruction: body.instruction, status: res.status(), ms: Date.now() - started, json });
  const brief = json.error ?? `${json.suggestions.length} placed, ${json.dropped.length} dropped, $${json.usage.costUsd?.toFixed(4)}`;
  console.log(`  api #${calls} ${body.mode}${body.scope ? " (scoped)" : ""}: HTTP ${res.status()} in ${Date.now() - started} ms · ${brief}`);
  await route.fulfill({ response: res, json });
});
page.on("pageerror", (e) => console.log("  pageerror:", e.message));
page.on("console", (m) => m.type() === "error" && console.log("  console error:", m.text()));

const shot = async (name) => {
  await page.waitForTimeout(300);
  await page.screenshot({ path: `${out}/${name}.png` });
  console.log(`shot ${name}`);
};
const doc = () => page.evaluate(() => window.__view.state.doc.toString());
const cards = page.locator(".sg-card");
const select = (pos) =>
  page.evaluate((p) => {
    window.__view.focus();
    window.__view.dispatch({ selection: { anchor: p }, userEvent: "select" });
  }, pos);

await page.goto(base, { waitUntil: "networkidle" });
await page.evaluate(() => document.fonts.ready);
const original = await doc();
await shot("01-start");

// 1. Review doc (Sonnet)
await page.getByRole("button", { name: "Review doc" }).click();
await page.waitForTimeout(900);
await shot("02-reviewing");
await page.locator(".topbar__status:not(:has(.shimmer-text))").waitFor({ timeout: 45_000 });
await page.waitForFunction(() => !document.querySelector(".cm-thinking"));
const n = await cards.count();
console.log(`review placed ${n} suggestions`);
await shot("03-suggestions");
if (n < 3) throw new Error(`need 3 suggestions for accept/reject/refine, got ${n}`);

// 2. accept the first card
await cards.nth(0).getByRole("button", { name: /Accept/ }).click();
await shot("04-accepted");

// 3. reject the (new) first card
await cards.nth(0).getByRole("button", { name: /Reject/ }).click();
await shot("05-rejected");

// 4. refine the remaining first card twice (Haiku)
const refineOnce = async (instruction, name) => {
  const card = cards.nth(0);
  await card.getByRole("button", { name: "Refine" }).click();
  await page.getByPlaceholder("How should it change?").fill(instruction);
  await shot(`${name}-asking`);
  const before = calls;
  await page.keyboard.press("Enter");
  await page.waitForFunction((b) => document.querySelectorAll(".sg-card.is-thinking").length === 0 && window.__calls > b, before, { timeout: 1 }).catch(() => {});
  await page.waitForFunction(() => !document.querySelector(".sg-card.is-thinking"), null, { timeout: 30_000 });
  await shot(name);
};
await refineOnce("shorter", "06-refined-1");
await refineOnce("more formal", "07-refined-2");

// 5. ⌘K Tighten on a paragraph without suggestions, typing above it while it runs (Haiku)
const candidates = ["New accounts now land", "Thanks to everyone", "We also simplified"];
let target = null;
for (const c of candidates) {
  const line = page.locator(".cm-line", { hasText: c.slice(0, 18) }).first();
  if ((await line.locator(".cm-sg-del, .cm-sg-ins").count()) === 0) {
    target = c;
    break;
  }
}
if (!target) throw new Error("no paragraph without suggestions for the ⌘K step");
console.log(`⌘K target: "${target}…"`);
await select((await doc()).indexOf(target) + 5);
await page.keyboard.press("ControlOrMeta+k");
await page.getByRole("button", { name: "Tighten" }).click();
await page.getByText("Thinking…").waitFor();
const h1End = (await doc()).indexOf("\n");
await select(h1End);
await page.keyboard.type(" (draft)", { delay: 25 });
await shot("08-typing-while-thinking");
await page.waitForFunction(() => !document.querySelector(".cm-thinking"), null, { timeout: 30_000 });
await shot("09-after-typing");

const final = await doc();
writeFileSync(`${out}/run.json`, JSON.stringify({ original, final, log }, null, 2));
console.log(`typed text kept: ${final.split("\n")[0].endsWith(" (draft)")}`);
console.log(`model calls: ${calls}`);
await browser.close();

