import { chromium } from "playwright";
const b = await chromium.launch();
const page = await b.newPage({ viewport: { width: 1440, height: 960 } });
await page.route("**/api/suggest", async (r) => {
  await new Promise((x) => setTimeout(x, 800));
  const d = r.request().postDataJSON();
  const at = d.doc.indexOf("three-step");
  await r.fulfill({ json: { note: "n", suggestions: [{ id: "a", from: at, to: at + 10, quote: "three-step", replacement: "3-step", reason: "r" }], dropped: [], usage: { inputTokens: 0, outputTokens: 0, costUsd: 0, latencyMs: 1 } } });
