import { readFileSync } from "node:fs";
import { suggest } from "@/lib/server/suggest";
process.loadEnvFile(".env");
const run = JSON.parse(readFileSync("design/screenshots/live/run.json", "utf8"));
const doc: string = run.final;
const r3 = run.log.find((e: { call: number }) => e.call === 3).json.suggestions[0];
const from = doc.indexOf(r3.quote);
const target = { from, to: from + r3.quote.length, quote: r3.quote, replacement: r3.replacement, history: [{ instruction: "shorter", replacement: r3.replacement }] };
let cost = 0;
for (let i = 1; i <= 3; i++) {
  const res = await suggest({ mode: "refine", doc, instruction: "more formal", target }, { apiKey: process.env.OPENROUTER_API_KEY!, model: "anthropic/claude-haiku-5.5" });
  cost += res.usage.costUsd ?? 0;
  const s = res.suggestions[0];
  const applied = s ? doc.slice(0, s.from) + s.replacement + doc.slice(s.to) : doc;
  const line = applied.split("\n").find((l) => l.startsWith("New accounts"))!;
  const bad = /\bIn (In|during)\b/i.test(line);
  console.log(`#${i} ${bad ? "BROKEN" : "ok    "} …${line.slice(line.indexOf("page.") , line.indexOf("page.") + 120)}…`);
}
console.log(`cost $${cost.toFixed(4)}`);
EOF
