for i in $(seq 1 40); do curl -s -o /dev/null http://localhost:3123/ && break; sleep 1; done; cat > scripts/.dark-shot.mjs <<'EOF'
import { chromium } from "playwright";
const mock = process.argv.includes("--mock");
const out = process.argv[3];
const b = await chromium.launch();
const page = await b.newPage({ viewport: { width: 1440, height: 960 }, colorScheme: "dark" });
let calls = 0;
await page.route("**/api/suggest", async (route) => {
  if (++calls > 1) return route.abort(); // budget guard: one model call
  if (mock) {
    const d = route.request().postDataJSON().doc;
    const at = d.indexOf("We are pleased");
    return route.fulfill({ json: { note: "Mock.", suggestions: [{ id: "m", from: at, to: at + 14, quote: "We are pleased", replacement: "We're glad", reason: "Mock." }], dropped: [], usage: { inputTokens: 0, outputTokens: 0, costUsd: 0, latencyMs: 1 } } });
  }
  const res = await route.fetch();
  const json = await res.json();
  console.log(`api: HTTP ${res.status()} · ${json.error ?? `${json.suggestions.length} placed, ${json.dropped.length} dropped, $${json.usage.costUsd?.toFixed(4)}`}`);
  await route.fulfill({ response: res, json });
});
await page.goto(process.argv[2], { waitUntil: "networkidle" });
await page.evaluate(() => document.fonts.ready);
await page.getByRole("button", { name: "Review doc" }).click();
await page.locator(".topbar__status:not(:has(.shimmer-text))").waitFor({ timeout: 45_000 });
await page.waitForFunction(() => !document.querySelector(".cm-thinking"));
await page.mouse.move(5, 900); // no hover state on the button
await page.waitForTimeout(600);
await page.screenshot({ path: out });
console.log(`cards: ${await page.locator(".sg-card").count()} · theme: ${await page.evaluate(() => matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light")} · calls: ${calls}`);
await b.close();
EOF
node scripts/.dark-shot.mjs http://localhost:3123 "$TMPDIR/dark-mock.png" --mock

